  --color-primary-text: #ffffff;
  --color-text: #1a1a2e;
  --color-text-muted: #6b7280;
  --color-check-bg: #6c63ff;
  --color-success-bg: #ecfdf5;
  --color-success-border: #6ee7b7;
  --color-success-text: #065f46;
  --color-error-bg: #fef2f2;
  --color-error-border: #fca5a5;
  --color-error-text: #991b1b;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 1px 3px rgba(0,0,0,0.07), 0 4px 16px rgba(0,0,0,0.06);
  --transition: 150ms ease;
}

body {
  background: var(--color-bg);
  color: var(--color-text);
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  min-height: 100vh;
  padding: 40px 16px 80px;
}

.page-wrapper {
  max-width: 640px;
  margin: 0 auto;
}

/* Header */
.quiz-header {
  margin-bottom: 32px;
}

.quiz-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: rgba(108, 99, 255, 0.1);
  border-radius: 20px;
  padding: 4px 12px;
  margin-bottom: 12px;
}

.quiz-title {
  font-size: 28px;
  font-weight: 750;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: var(--color-text);
  margin-bottom: 8px;
}

.quiz-subtitle {
  color: var(--color-text-muted);
  font-size: 14px;
}

/* Progress */
.progress-bar-track {
  height: 4px;
  background: var(--color-border);
  border-radius: 99px;
  margin-bottom: 32px;
  overflow: hidden;
}

.progress-bar-fill {
  height: 100%;
  background: var(--color-primary);
  border-radius: 99px;
  transition: width 0.4s ease;
}

/* Form field */
.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 24px;
  margin-bottom: 16px;
  box-shadow: var(--shadow);
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.question-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.question-number {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: rgba(108, 99, 255, 0.1);
  border-radius: 6px;
  padding: 2px 8px;
}

.question-badge {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-text-muted);
  background: var(--color-bg);
  border-radius: 6px;
  padding: 2px 8px;
}

.question-text {
  font-size: 16px;
  font-weight: 650;
  color: var(--color-text);
  line-height: 1.4;
  margin-bottom: 6px;
}

/* Help text */
.help-text {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  font-size: 13px;
  color: var(--color-text-muted);
  background: #f8f7ff;
  border: 1px solid #e0deff;
  border-radius: var(--radius-sm);
  padding: 9px 12px;
  margin-bottom: 18px;
  line-height: 1.5;
}

.help-text svg {
  flex-shrink: 0;
  margin-top: 1px;
}

/* Options list */
.options-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 14px;
}

.option-item {
  position: relative;
}

.option-item input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.option-label {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), box-shadow var(--transition);
  user-select: none;
}

.option-label:hover {
  background: #f8f7ff;
  border-color: #c4bfff;
}

.option-item input[type="checkbox"]:focus-visible + .option-label {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.option-item input[type="checkbox"]:checked + .option-label {
  background: #f0eeff;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.12);
}

/* Custom checkbox box */
.checkbox-box {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  border: 1.5px solid #c9c6d1;
  border-radius: 5px;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition), border-color var(--transition);
}

.option-item input[type="checkbox"]:checked + .option-label .checkbox-box {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}

.checkbox-check {
  display: none;
}

.option-item input[type="checkbox"]:checked + .option-label .checkbox-check {
  display: block;
}

.option-text {
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text);
  flex: 1;
}

.option-item input[type="checkbox"]:checked + .option-label .option-text {
  color: var(--color-primary);
  font-weight: 600;
}

/* Submit button */
.submit-row {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 8px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 650;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  border: none;
  outline: none;
}

.btn:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

.btn-ghost {
  background: transparent;
  color: var(--color-text-muted);
  border: 1.5px solid var(--color-border);
}

.btn-ghost:hover {
  background: var(--color-bg);
  color: var(--color-text);
}

.btn-primary {
  background: var(--color-primary);
  color: var(--color-primary-text);
  box-shadow: 0 2px 8px rgba(108, 99, 255, 0.35);
}

.btn-primary:hover {
  background: var(--color-primary-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(108, 99, 255, 0.4);
}

.btn-primary:active {
  transform: translateY(0);
}

