  const label    = el("label", { className: "option-label", htmlFor: inputId }, checkBox, optText);
  const input    = el("input", {
    type: "checkbox",
    id: inputId,
    name: questionId,
    value: option.id,
    onChange() {
      if (this.checked) state.answers[questionId].add(option.id);
      else              state.answers[questionId].delete(option.id);
      updateProgress();
    },
  });

  return el("div", { className: "option-item" }, input, label);
}

function OptionsList({ question }) {
  const items = question.options.map(opt =>
    CheckboxOption({ questionId: question.id, option: opt })
  );
  return el("div", { className: "options-list" }, ...items);
}

function HelpText({ text }) {
  const icon = svgIcon(ICONS.info, 14);
  return el("div", { className: "help-text" }, icon, text);
}

function QuestionCard({ question }) {
  const meta = el("div", { className: "question-meta" },
    el("span", { className: "question-number" }, `Question ${question.number}`),
    el("span", { className: "question-badge" }, "Select all that apply"),
  );
  const questionText = el("p", { className: "question-text" }, question.text);
  const help = question.helpText ? HelpText({ text: question.helpText }) : null;
  const options = OptionsList({ question });

  return el("div", { className: "form-field" }, meta, questionText, help, options);
}

function SubmitButton() {
  const arrowIcon = svgIcon(ICONS.arrow, 14);
  return el("button", {
    type: "submit",
    className: "btn btn-primary",
    id: "submit-btn",
  }, "Submit Quiz", arrowIcon);
}

function ResetButton() {
  return el("button", {
    type: "button",
    className: "btn btn-ghost",
    id: "reset-btn",
    onClick: resetQuiz,
  }, "Retake Quiz");
}

function ResultItem({ question, userAnswers }) {
  const correct   = new Set(question.correct);
  const answered  = userAnswers;
  const isCorrect =
    answered.size === correct.size &&
    [...answered].every(a => correct.has(a));

  const correctLabels = question.options
    .filter(o => correct.has(o.id))
    .map(o => o.label)
    .join(", ");

  const icon = svgIcon(isCorrect ? ICONS.check : ICONS.x, 15);
  const textNode = el("div", { className: "result-item-text" },
    el("strong", {}, `Q${question.number}: ${question.text}`),
    isCorrect
      ? `Correct! The answers are: ${correctLabels}.`
      : `Incorrect. The correct answers are: ${correctLabels}.`
  );

  return el("div", { className: `result-item ${isCorrect ? "correct" : "incorrect"}` },
    el("span", { className: "result-icon" }, icon),
    textNode
  );
}

function ResultsPanel({ score, total }) {
  const label =
    score === total ? "Perfect score! 🎉" :
    score >= total / 2 ? "Good effort!" : "Keep learning!";

  const circle = el("div", { className: "results-score-circle" },
    el("span", { className: "results-score-value" }, `${score}/${total}`)
  );
  const title = el("h2", { className: "results-title" }, label);
  const desc  = el("p",  { className: "results-desc"  },
    `You got ${score} out of ${total} questions correct.`
  );
  const breakdown = el("div", { className: "results-breakdown" },
    ...QUIZ_DATA.map(q => ResultItem({ question: q, userAnswers: state.answers[q.id] }))
  );
  const divider = el("div", { className: "divider" });
  const resetBtn = ResetButton();

  const panel = el("div", { className: "results-panel", id: "results-panel" },
    circle, title, desc, breakdown, divider, resetBtn
  );

  return panel;
}

// ─── Quiz logic ───────────────────────────────────────────────────────────────

function updateProgress() {
  const answered = QUIZ_DATA.filter(q => state.answers[q.id].size > 0).length;
  const pct = (answered / QUIZ_DATA.length) * 100;
  document.getElementById("progress-fill").style.width = pct + "%";
}

function scoreQuiz() {
  return QUIZ_DATA.reduce((acc, q) => {
    const correct  = new Set(q.correct);
    const answered = state.answers[q.id];
    const ok =
      answered.size === correct.size &&
      [...answered].every(a => correct.has(a));
    return acc + (ok ? 1 : 0);
  }, 0);
}

function handleSubmit(e) {
  e.preventDefault();
  const score = scoreQuiz();
  const panel = ResultsPanel({ score, total: QUIZ_DATA.length });

  const container = document.getElementById("quiz-container");
  container.style.display = "none";

  const results = document.getElementById("results-panel");
  if (results) results.remove();

  document.getElementById("page-wrapper").appendChild(panel);
  requestAnimationFrame(() => panel.classList.add("visible"));
  panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function resetQuiz() {
  QUIZ_DATA.forEach(q => { state.answers[q.id] = new Set(); });

  document.querySelectorAll('input[type="checkbox"]').forEach(cb => {
    cb.checked = false;
  });

  document.getElementById("results-panel")?.remove();
  const container = document.getElementById("quiz-container");
  container.style.display = "";
  updateProgress();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

