function mount() {
  const app = document.getElementById("page-wrapper");

  // Header
  const eyebrow = el("div", { className: "quiz-eyebrow" }, "🖥️  Computer Languages Quiz");
  const title   = el("h1", { className: "quiz-title" }, "How well do you know programming languages?");
  const sub     = el("p",  { className: "quiz-subtitle" }, "Select all correct answers for each question, then submit.");
  const header  = el("header", { className: "quiz-header" }, eyebrow, title, sub);

  // Progress
  const fill  = el("div", { className: "progress-bar-fill", id: "progress-fill", style: "width:0%" });
  const track = el("div", { className: "progress-bar-track" }, fill);

  // Questions
  const cards = QUIZ_DATA.map(q => QuestionCard({ question: q }));

  // Submit row
  const submitRow = el("div", { className: "submit-row" }, SubmitButton());

  // Form
  const form = el("form", { id: "quiz-container", onSubmit: handleSubmit },
    track,
    ...cards,
    submitRow
  );

  app.appendChild(header);
  app.appendChild(form);
}

document.addEventListener("DOMContentLoaded", mount);
